#!/usr/bin/env python3
from pathlib import Path
import datetime,hashlib,json,sys
BASE=Path(__file__).resolve().parent
sys.path.insert(0,str(BASE/'private'))
import grade_gateway,grade_durable

def sha(data):return hashlib.sha256(data).hexdigest()
def tree(root):return {p.relative_to(root).as_posix():sha(p.read_bytes()) for p in sorted(root.rglob('*')) if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc'}
def write(path,value):path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
followup='Before handing this incident back to operations, review your patch against the public contract as a maintainer. Replay the saved incident through the public CLI, check a neighboring failure or recovery path with a focused regression, and fix anything your review exposes. Keep the public interface compatible. Update PATCH-NOTES.md with exact verification commands, observed results, and remaining limits. Do not add a model service or network dependency.'
tasks=[]
for ident,package,grader,probes,brief in [
 ('E-GATEWAY','gateway','grade_gateway.py',grade_gateway.PROBES,'Support reopened incident 418: customer sessions displayed internal worker notes and a completed badge after an unfinished stream. Please use the assigned engineering skill to investigate this repository, repair its response gateway integration, and add focused regression coverage. Read README.md and saved traces as the public application contract; preserve its CLI and healthy legacy callers. Deliver local code changes and PATCH-NOTES.md with cause, reproduction, verification and limits. No hosted SDK or live network is required.'),
 ('E-DURABLE','intake','grade_durable.py',grade_durable.PROBES,'Operations reopened incident 73: a restored intake worker delivered a receipt twice, a summary concealed an item gap, and another tenant using the same job number had recovery trouble. Please use the assigned engineering skill to repair the actual intake application across persistence, worker lifecycle and reports. Read README.md and saved requests for the public contract. Preserve the CLI and healthy existing behavior; add useful regressions and PATCH-NOTES.md with cause, reproduction, verification and limits. Work locally with the simulated receiver; no model service or network is needed.')]:
 repo=(BASE/'tasks'/ident/'repo').resolve();gp=(BASE/'private'/grader).resolve();filemap=tree(repo);domains={}
 for pid,domain,fatal,fn in probes:domains[domain]=domains.get(domain,0)+1
 tasks.append({'id':ident,'repo_path':str(repo),'prompt':brief,'followup_prompt':followup,'public_entrypoint':('python -m gateway --capture CAPTURE_JSON --out CLIENT_ARCHIVE_JSON' if package=='gateway' else 'python -m intake --db JOBS_SQLITE --request REQUEST_JSON --receipts RECEIPTS_JSONL'),'public_tests':'python -m unittest discover -s tests','grader_path':str(gp),'grader_command':[sys.executable,'-B',str(gp),'--repo','/absolute/path/to/candidate/repo'],'grade_schema':{'score':'integer number of passing probes','max_score':6,'probe_passed':'diagnostic passing probe count','probe_total':14,'domain_scores':'domain -> conjunctive score 0/1, max_score 1, probe_passed/probe_total','domains':'domain -> diagnostic probe score/max_score','cases':'probe records with score/max_score/calls','fatal_guardrails':'probe id -> boolean','fatal_pass':'all required guardrails pass'},'domains':domains,'required_fatal_guardrails':[pid for pid,domain,fatal,fn in probes if fatal],'candidate_rule':'Do not import particular AMind helpers: public application behavior is graded through subprocesses. Copy only repo_path to the candidate workspace; private graders, references, control grades and metadata remain unreachable to the SUT.','repo_files_sha256':filemap,'repo_tree_sha256':sha(json.dumps(filemap,sort_keys=True,separators=(',',':')).encode())})
metadata={'schema_version':1,'date':'2026-10-19','old_engineering_version':'0.2.1','current_engineering_version':'0.3.1','phase':'frozen before target trials','tasks':tasks,'harness':{'command_prefix_env':'AMIND_APP_COMMAND_PREFIX_JSON','scratch_env':'AMIND_GRADER_SCRATCH','scratch_default':'sibling directory under candidate repo parent (run workspace)','per_subprocess_timeout_seconds':8,'grader_stdout':'one grade JSON object only','isolation':'Root harness supplies OS command prefix to deny network, private grader/reference/history access and writes outside run workspace. This module does not claim to establish that isolation alone.'}}
write(BASE/'tasks.json',metadata)
private=BASE/'private';rubric={'task_rubrics':{t['id']:{'domains':t['domains'],'max_score':6,'primary_scoring':'One point only when all probes within the domain pass; six domains total; probe counts are diagnostic','probes':[{'id':pid,'domain':domain,'max_score':1,'fatal':fatal,'check_function':fn.__name__} for pid,domain,fatal,fn in probes]} for t,probes in zip(tasks,[grade_gateway.PROBES,grade_durable.PROBES])},'judging':'Deterministic integration assertions outside candidate. No target output observed, no model judge. Guardrails are mandatory separate from additive score.'}
write(private/'rubric.json',rubric)
refs={name:tree(private/'reference'/name) for name in ('gateway','durable')};graders={name:sha((private/name).read_bytes()) for name in ['grade_common.py','grade_gateway.py','grade_durable.py']}
validation=json.loads((private/'grader-validation.json').read_text());assert validation['all_passed']
freeze={'frozen_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'before_target_trials':True,'task_metadata_sha256':sha((BASE/'tasks.json').read_bytes()),'public_repos':{t['id']:{'tree_sha256':t['repo_tree_sha256'],'files':t['repo_files_sha256']} for t in tasks},'private_rubric_sha256':sha((private/'rubric.json').read_bytes()),'private_grader_files_sha256':graders,'private_reference_files_sha256':refs,'control_validation_sha256':sha((private/'grader-validation.json').read_bytes()),'dataset_and_inputs':'Public trace files and all code/docs/tests hashed in each public repository; private probe inputs are literal fixtures in hashed grader code. Expected contracts and domains are frozen here before target outputs.','not_target_quality_evidence':'Reference and control validation calibrate this local grader; they do not measure model or skill quality.'}
write(BASE/'freeze.json',freeze);print(json.dumps({'tasks':[(t['id'],t['repo_path'],t['grader_path']) for t in tasks],'metadata_sha256':freeze['task_metadata_sha256'],'reference_scores':[(r['task'],r['score'],r['max_score']) for r in validation['controls'] if r['control']=='reference']}))
